	title 'Desk Manager--CDAMenu'************************************************************************ Desk Manager--CDAMenu for the Apple II GS** Original CDA code by John Worthinton.* Original NDA code by Steven Glass** Additions and alterations by Steven Glass and* Konstantin Othmer** This file contains all the code necessary to handle the CDA menu.** The procedures in this file are:**	DAHandler*	DoCDAMenu*	DisplayData*	SortCDAs*	ChooseCDA*	InitStuff*	GotReturn*	MonKeyIn*	EvntKeyIn*	Pg2Kludge*	UpdateCDAMenu*	PrintDAList*	WriteDAName*	SetUpTab*	OpenDA*	Deref***********************************************************************************************************************************************			         **	Copyright (C) 1985-1991	         **	Apple Computer, Inc.	         **	All Rights Reserved		         **			         ************************************************************************* 26-Sep-90	Dave Lyons** Change setmode8 to shortmx, setmode16 to longmx.** 27-Nov-90	Dave Lyons** Added SortCDAs routine, and made ChooseCDA call it.* Optimized a few bytes from cout.** 12-Feb-91	Dave Lyons** Changed the GetNextEvent call to use event mask $0028 instead of* $FFFF (we don't want to get update events and cause CheckUpdate* calls, since this interferes with QuickDraw debugging!).** 30-Sep-91	Dave Lyons** Added support in MyWriteline for Ctrl-N to cancel Inverse text,* since the Text.Clock CDA uses this:  "[Text Clock]: on"************************************************************************* 7-Jul-92	Dave Lyons** PanelActive checks ROM version using FWEntry before trying to check* for the ROM 3 Control Panel disable jumper using ReadKeyMicroMemory.***********************************************************************	msb ON	include 'all.macros'	include '::sys.equs.asm'	include 'e16.memory';=================================================;; Special Macros;	MACRO&lab	movelong &src,&dest&lab	lda &src	sta &dest	lda &src+2	sta &dest+2	mendDAVersionNumber	equ $8301	;8300Slot_Arbiter	equ $E10208	include 'Desk.Equates.asm'	title 'CDAMenu--DAhandler'*****************************************************************DAHandler	PROC EXPORT** This is the code that handles Desk Accessory interrupts.* When a CDA interrupt occurs, this handler gets control* in 8-bit native mode.  It decides whether actually put* up the CDA menu or schedule an event.** Note that this handler does not get called if the EventManger* is active.  In that case, the Event Manager installs its own* interrupt handler whose job it is to post events.*** Inputs:*	none** Outputs:*	carry clear indicates that interrupt*	is handled.** External Refs:	import DoCDAMenu** Entry Points:*	none*	longa off	; mode	longi off** Change History** 19 Jul 88	Steven Glass** This code used to be part of the procedure DABootInit.  It is* now separate and more self contained.  *****************************************************************	php	; save status register;-----------------------------------------------------------;; Check the global variable NumInts.  If this number is; is negative, we aren't alread in the CDA menu.  This; prevents multiple entries into the CDA menu.;	lda >numints	inc a	bne AllDone;-----------------------------------------------------------;; Check the busy flag.  If it is not zero, we schedule; an interrupt.  If it is zero, we go ahead now.;	lda >busyflag	; if busyflg is 0 then we can	bne ScheduleIt	jsl DoCDAMenu	bra AllDoneScheduleIt	longmx	; switch to full native to make call	pha	; space for result	PushLong #DoCDAMenu ; get in the scheduler's que	_SchAddTask	pla	; ignore result	shortmx	; switch back to 8-bit native	lda #$FF	; reset the NumInts variable	sta >numintsAllDone	plp	; restore P	clc	; claim the interrupt	rtl	; all done.	ENDP	title 'CDAMenu--DoCDAMenu'*****************************************************************DoCDAMenu	PROC** This is the routine that is called to display the CDA* menu.  It is either called by the DA interrupt handler* (if it is safe to do so) or by the scheduler.** This code can be called in either 8, or 16 bit native* mode and should work fine.** This code resets the variable NumInts to $FF and it sets* the next byte after it (mmode) to zero.  Why it does this* is not really know, but must accesses to NumInts seem* to trash mmode.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 19 Jul 88	Steven Glass** This code used to be part of the procedure DABootInit.  It is* now separate and more self contained.  The same code is called* in the same way whether or not the scheduler is used.** This code used to save and restore the dbr around the * code that moved the stack.  Instead, we save and restore the dbr at* the same time as the processor.***************************************************************** 	php	; save m&x bits	phb	; save dbr	longmx	; now in full native mode.	tsc	; save stack for integer basic	sta >stacksv; Save stack but don't worry about changing data bank.; it is saved above and restored below with P.;	ldx #$0100	; stack is saved as $E0/0300	ldy #$0300	lda #$FF	mvn $000000,$E00000	lda #$1FB	; make sure there's room on stack	tcs	_SaveAll	; save everything	_ChooseCDA	; display the list of da's	_RestAll	; unsave everything	lda #$FF	; clear numints on exit	sta >numints	; trash next byte too!!!!!!!!!!!!!!	ldx #$0300	; move stack from buffer back to 	ldy #$0100	; page 1.	lda #$FF	mvn $E00000,$000000	lda >stacksv	; restore stack pointer.	tcs	plb	; restore dbr	plp	; restore m & x bits.	rtl	ENDP	title 'CDAMenu--DisplayData'displaydata	PROC EXPORT	EXPORT topofmenutopofmenu	DC.B $A0	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $DF	DC.B $A0,$00	EXPORT mainstrmainstr	DC.B $5A,$A0,$41,$A0	DC.B 'Desk Accessories '	DC.B $20	DC.B $20	DC.B $20	DC.B $20	DC.B $20	DC.B $20	DC.B $20	DC.B $20	DC.B $20	DC.B $20	DC.B $20	DC.B $20	DC.B $20	DC.B $20	DC.B $20	DC.B $20	DC.B $20	DC.B $20	DC.B $5F,$00	EXPORT bottmofmenubottmofmenu	DC.B $5A	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $5F,$00;	EXPORT midstr;midstr	DC.B $5A;	DC.B $FF,$24,$A0;	DC.B $5F,$00	EXPORT selectstrselectstr	DC.B $5A	DC.B ' Select: '	DC.B $4A,$A0,$4B	DC.B $A0	DC.B $A0	DC.B $A0	DC.B $A0	DC.B $A0	DC.B $A0	DC.B $A0	DC.B $A0	DC.B $A0	DC.B $A0	DC.B $A0	DC.B $A0	DC.B $A0	DC.B $A0	DC.B $A0	DC.B $A0	DC.B $A0	DC.B 'Open: '	DC.B $4D,$A0,$A0,$5F,$00	EXPORT laststrlaststr	DC.B $A0	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $4C	DC.B $00	EXPORT uparrowsuparrows*** Commented out the text because it's exactly the same as downarrows.  12-Feb-91 DAL***	DC.B $5B,$5B,$5B,$A0,'more',$A0,$5B,$5B,$5B ;up arrows are 4B***	DC.B $00	EXPORT downarrowsdownarrows	DC.B $5B,$5B,$5B,$A0,'more',$A0,$5B,$5B,$5B ;down arrows are 4A	DC.B $00	EXPORT blanklineblankline	DC.B '                                    '	DC.B $00	EXPORT dastrdastr	DC.L mainstr	DC.L cntrlstr	DC.L quitstr	DC.L selectstr	EXPORT cntrlstrcntrlstr	DC.B 'Control Panel'	DC.B $00	EXPORT quitstrquitstr	DC.B 'Quit'	DC.B $00	ENDP****************************************************************** SortCDAs  27-Nov-90 DAL** If bit 0 of battery-RAM location $5F is on, we sort the CDA* handles into alphabetical order before displaying the menu.** ChooseCDA calls SortCDAs (from RAM on ROM 1, and through a* patch to ROM 3).*****************************************************************SortCDAs	proc export	pha	;space for result	pea $5F	_ReadBParam	pla	lsr a	bcc cdaDontSortswapFlag	equ 1counter	equ swapFlag+2str1	equ counter+2str2	equ str1+4myPtr	equ str2+4	lda >NumDAs	beq @SortDone	;if there aren't any, we're done	dec a	beq @SortDone	;if there's only one, we're done	phd	lda >CDATabHndl+2	pha	lda >CDATabHndl	pha	phx	phx	;space for str2	phx	phx	;space for str1	phx	;space for counter	phx	;space for swapFlag	tsc	tcd** deref myPtr=CDATabHndl into pointer	ldy #2	lda [<myPtr],y	tax	lda [<myPtr]	sta <myPtr	stx <myPtr+2	jsr cdaDoTheSort	plx	plx	plx	plx	plx	plx	plx	plx	pld@SortDonecdaDontSort	rts** cdaDoTheSort** Input: myPtr = pointer to the list of CDA handles*        >NumDAs = number of CDAs (AT LEAST 2!)** Output: the handles in myPtr are sorted so that the*         CDAs are in alphabetical order** Uses:  swapFlag, counter, str1, str2 (on dp/stack)** The sort ignores bit 7 and ignores case.*cdaDoTheSort	lsr <swapFlag	ldy #0	;index into myPtr (list of handles)	lda >NumDAs	dec a	sta <counter@checkPair	phy	jsr GetCDANamePtr	stx <str1+2	sta <str1	iny	iny	iny	iny	jsr GetCDANamePtr	stx <str2+2	sta <str2	jsr CompareDANames	bcc @noSwap	ror <swapFlag	;set bit 15 = we had to swap something	ply	phy	jsr SwapYandNext@noSwap	ply	iny	iny	iny	iny		dec <counter	bne @checkPair	bit <swapFlag	bmi cdaDoTheSort	rts** GetCDANamePtr** Input: Y = index into handle list (preserved)*        <myPtr = pointer to list of handles** Output: XA = pointer to CDA (name)*GetCDANamePtr	phy	lda [<myPtr],y	tax	iny	iny	lda [<myPtr],y	;got XA = handle to a CDA	phd	pha	phx	;push handle on stack for dereference	tsc	tcd	ldy #2	lda [1],y	tax	;return high word of pointer	lda [1]	;return low word of pointer	ply	;throw away handle	ply	;throw away handle	pld	;restore D	ply	;restore caller's Y	rts** CompareCDANames** Input: str1, str2** Output: CLC if DAs are correctly ordered*CompareDANames	ldy #0@pchar	tya	sep #$20	cmp [<str1]	rep #$20	bcs @clc	;return with carry clear (hit end of first string)	sep #$20	cmp [<str2]	rep #$20	bcs @rts	;return with carry set (hit end of 2nd string)	iny	lda [<str2],y	jsr @upcase	sta >@cheat+1	lda [<str1],y	jsr @upcase@cheat	cmp #$7777	;self-modified	beq @pchar@rts	rts	;returns carry@upcase	and #$007f	cmp #'a'	bcc @1	cmp #'z'+1	bcs @1	and #$df@clc	clc@1	rts** SwapYandNext** Input: Y = index to a handle in the <myPtr list** Swaps the handle with the one following** Trashes A, X, Y.*SwapYandNext	ldx #4	phy@push	lda [<myPtr],y	pha	iny	iny	dex	bne @push	lda 9,s	;get old index back	tay	plx	pla	;XA=2nd handle	sta [<myPtr],y	iny	iny	txa	sta [<myPtr],y	plx	pla	;XA=old first handle	iny	iny	sta [<myPtr],y	iny	iny	txa	sta [<myPtr],y	ply	rts	EndP*****************************************************************ChooseCDA	PROC EXPORT** ChooseCDA is the internal routine that causes the CDA menu* to be displayed.** The system must already be in text mode before this call is* made.  This call assumes that stack and d-page are already* set to page 1 and page 0.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*** Change History:**  Halloween	Kontstantin Othmer**   Added warm entry point so that current state of desk manager* is saved and returned to after the cda call is done.* Also took out all the brks.*****************************************************************	jsr SortCDAs	;added 27-Nov-90 DAL	phb	; save dbr	lda #0	sta >firstMenuItem	; tell UpdateCDA to start at item 0	sta >curCDA	; select item 0 (control panel)		lda #$0003	;request current bit encoded configuration	jsl Slot_Arbiter	;and make slot 3 internal	phx	;saves bit encoded configuration		ENTRY ChooseCDAWarmChooseCDAWarm 	pea $E0E0	;Reset dbr to bank $E0	plb	plbSkipWarm	jsr initstuff	;This inits all formatting parameters	pea $FF	; and mask	pea $00	; or mask	_SetOutGlobals	pea 00	; device type	pushlong #$03	; pointer to driver	_SetOutputDevice** Determine whether or not we have an 80 column card*  Later we will use this information for setting the position of the menu*  In 40 column mode, the menu starts in column 0*  In 80 column mode, the menu starts in column 20*loop13	shortmx	ldx #$00	; check for 80-col card in placeloop4card	lda $C305	cmp #$38	bne nocard	lda $C307	cmp #$18	bne nocard	inx	bne loop4card	bra cz2nocard	sta |setintc3rom	; just to make sure	its really in	bra loop4cardcz2	lda #$FF	sta >$000032	; turn off inverse	longmx	pea 01	; init device to output	_InitTextDevcz3	PushWord #00	PushWord #$19	; want 40 cols	_ReadBParam	pla	and #$00FF	sta |sv4080	bne c1	;not 40 column; everything is ok; From here to c1 is 40 column init.; Initstuff assumes 80 columns.; The only difference is the position of the left border	lda #$11	;Special 40 column init stuff	jsr cout	sep #$20	sta >$00C000	sta >$00C00C	rep #$20	lda #LeftBorder40	;Only difference between 80 & 40 is left	sta |leftborder	;column starting location	lda #LeftBorder40-3	sta |hpos	;menu border starts two to the left of textc1		 	lda #>topofmenu	sta temp2+1	lda #<topofmenu	sta temp2	jsr mywritecstringnt	inc |vpos	lda |dastrptr	; mainstr for international	sta temp1	lda |dastrptr+2	sta temp1+2	ldy #$02	lda [temp1],y	sta temp2+2	lda [temp1]	sta temp2	jsr MyWriteCStringnt ;Draws the Desk Accessories line	inc |vpos	lda #>bottmofmenu	sta temp2+1	lda #<bottmofmenu	sta temp2	jsr MyWriteCStringnt ;Draws the bar under Desk Access.;; Now print right and left borders of menu;	pushword #$14	;$14 = 20 lines of bars in all	lda |hpos	pha	;save to use in following routineloop		lda 1,s	sta |hpos	inc |vpos	pla	plx	dex	beq cont	;Leave loop if borders are done	phx	pha	lda #$5A	;Left Border Bar Character	jsr MyCout	lda 1,s	;replaces pla pha	clc	adc #WindowWidth	;Right Border = LeftBorder + Width	sta |hpos	lda #$5F	;Right Border Bar Char	jsr MyCout		bra loopcont	lda |dastrptr	; mainstr for international	sta temp1		lda |dastrptr+2	sta temp1+2	ldy #$0E	lda [temp1],y	sta temp2+2	dey	dey	lda [temp1],y	sta temp2	jsr MyWriteCstringnt ;draw bottom  "Select:....	inc |vpos		lda #>laststr	sta temp2+1	lda #<laststr	sta temp2	jsr MyWriteCStringnt ;Draws the bar under Desk Access.	;; if control panel active goto panelactive;	jsr panelactive	lda |numdas	;calculate last vertical position which	bcc active	dec aactive		clc	;contains text	adc #$05	;This is used to know where quit will be	cmp #Top+NumLines-1 ;last line a DA can show on	blt ok	lda #Top+NumLines-1ok	sta |bottomline	;save last text position	jsr UpdateCDAMenu	;draw all available CDAs;; Calculate position to draw selected (inverted) item; Postion is top+(curcda-firstmenuitem);	lda |curcda	sec	sbc |firstmenuitem	clc	adc #top	sta |vpos	;invert string routine which inverts	lda |leftborder	;the DA with some given number	sta |hpos	lda #$FF	; inverse	ldy |curcda	;Item to highlight	jsr writedaname	;Always start by selecting first itemloop1	per ret-1	lda |keyinput	;simulate a jsr through |keyinput	dec a	;(which isn't in the program bank!)	pha	rts;; Read keyboard and dispatch to appropriate routine;	longa on	longi onret	and #$7F	cmp #$0D	;Open CDA?	bne contt	jmp gotreturn	;Open itcontt	cmp #$0B	;up arrow?	bne contt1	brl upalinecontt1	cmp #$0A	;down arrow?	beq downaline	cmp #$1B	;escape key***	bne loop1	bne @notESC	brl DoEscape** Added 12-Feb-91 DAL.  If they didn't type something special, try* to jump to the next CDA that starts with the character they* typed.*@notESC	longmx	cmp #$20	bcc loop1	pha	lda #0	ldy |curcda	jsr WriteDAName	pla	jsr SearchCDALetter*	jsr GetCDANum	;Quit = NumDAs+1	sec	sbc |FirstMenuItem	clc	adc #Top	sta |vpos*	ldy |curcda	lda #$ff	jsr WriteDAName	bra loop1* Support routines for possible inputs followdownaline	longmx	ldy |curcda	; unhighlight current da	lda #$00	jsr writedaname	lda |curcda	; if curcda = quit then do nothing	cmp #$FF	bne cont1*If quit is selected, do nothing.	lda |leftborder	sta |hpos	lda #$FF	bra drawnamcont1* first check to see if the apple key was also pressed.  If it was, we move by pages.	lda |ModKeyReg	;Modifier key register $c025	and #$0080	;apple key bit (page 124 harware ref)	bne DoPageDown* here we move down 1 line* first check if we need to scroll	lda |vpos	cmp #Top+NumLines-1	;are we at the bottom?	bne contt2	brl scrollitcontt2	lda |curcda	inc a	;bump to next cda	cmp |numdas	; if curcda > numdas ->	bcc nowrap1	beq nowrap1	lda #$FF	;set to quit	nowrap1	pha	inc |vpos	pladrawnam	sta |curcda	; hilight curcda	tay	lda #$FF	jsr writedaname	brl loop1	; loop againDoPageDown*Apple and the down arrow key were pressed	lda |firstmenuitem	clc	adc #numlines-1	;this is the number of bottom menu item	cmp |curcda	;is this the selected one?	beq DoPageDown1	;branch if it is*See if its over the end		cmp |numdas	;are we off the bottom of the menu?	beq DoPageDownOK	;less than or = to #das	bcc DoPageDownOK	;then we're not over the bottom	lda #$FF	;move to quit if off the end DoPageDownOK	pha	;if it isn't, select and drawit	lda |bottomline		sta |vpos	lda |leftborder	sta |hpos	pla	;a has curcda	bra drawnamDoPageDown1*We want to page down	inc a		sta |firstmenuitem	;page down by one	clc	adc #numlines-1	;item on new screen bottom	cmp |numdas	;is it valid	bcc DoPageD2 	;it's OK: scroll	beq DoPageD2	;it's Ok: scroll*We went off the bottom.  Make quit the selected item.	lda |numdas	sec	sbc #numlines-2	;-2 to make room for quit	bcs EndOfDown	;were're ok: branch.  A has new start loc.	lda #0	;less menu items than lines.  Start @ top EndOfDown	sta |firstmenuitem	jsr UpdateCDAMenu	lda #$FF	;quit item	phaEndOfDown1	lda |leftborder	sta |hpos	lda |bottomline	sta |vpos	pla	bra drawnamDoPageD2*Here we just want to scroll down one page (numlines)	pha	jsr UpdateCDAMenu	bra EndOfDown1		DoPageUp*Apple and the up arrow key were pressed	lda #top	sta |vpos	lda |leftborder	sta |hpos	lda |firstmenuitem	cmp |curcda	;are we at the top?	beq JumpUp	;branch if we are at top	sta |curcda	;set to top of screen	brl drawnamJumpUp	*Jump up one page (numlines)	sec	sbc #NumLines	;subtract from firstmenuitem	bcc GoToTop	;branch if it puts us over the topJumpUp1	sta |firstmenuitem	;otherwise we move up by one page	sta |curcda	jsr UpdateCDAMenu	;scroll	lda #top	;we are at the top	sta |vpos	lda |leftborder	sta |hpos	lda |curcda	brl drawnamGoToTop	lda #0	bra JumpUp1scrollit*we are on last line.  Bump da pointer, scoll, then inverse video to select	lda |curcda	inc a	cmp |numdas	bcc scrollit1	;branch if not on last item	beq scrollit1	lda #$FF	;no more CDA's.  Quit is last item.scrollit1	sta |curcda	;we have the new DA number	inc |firstmenuitem	;start display one item later	jsr UpdateCDAMenu	lda #Top+Numlines-1	sta |vpos	lda |leftborder	sta |hpos	lda |curcda	brl drawnamupaline	longmx	ldy |curcda	; unhighlight current da	lda #$00	jsr writedaname*move by pages?	lda |ModKeyReg	;Modifier key register $c025	and #$0080	;apple key bit (page 124 harware ref)	beq NoPageUp	brl DoPageUp	;jump by pagesNoPageUp	lda |curcda	; if curcda = cntrl	pan, wrap	bne cont2*We're at the top (control panel)  Don't wrap.  Do nothing.	lda |leftborder	sta |hpos	lda #0	brl drawnam*We're at the top (control panel)  cont2* not at control panel* check if we are at top	lda |vpos	cmp #top	beq scrollup	;if we're at the top we need to scroll up;;just move up a line; no scrolling necessary.  A contains vpos.;	dec a	sta |vpos	lda |curcda	cmp #$FF	bne cont4	lda |numdas	brl drawnamscrollup* Here we need to scroll up a line.  We know we're not @ the very top because* we weren't @ the control panel* We decrement firstmenuitem & redraw	dec |firstmenuitem	dec |curcda	jsr UpdateCDAMenu	lda #top	sta |vpos	lda |leftborder	sta |hpos	lda |curcda	brl drawnamcont4	dec a	brl drawnamDoEscape*here we select the quit item.	ldy |curcda	; unhighlight current da	lda #$00	jsr writedaname*Goto bottom*First calculate new firstmenuitem = numdas-numlinesselectquititem	lda |numdas	sec	sbc #numlines-2	;-2 because 1 for quit and one because	bcs selectok	lda #0selectok	sta |firstmenuitem	;we start with item 1 (ctrl. panel = 0)	lda #$FF	sta |curcda	jsr UpdateCDAMenu	lda |bottomline	sta |vpos	lda #$FF	;quit item	brl drawnam	ENTRY DONEdone		;       	shortmx	lda #$FF	sta $000032	; inverse flag	longmx		plx	;get bit encoded slot configuation	lda #$0300	jsl Slot_Arbiter	;restore original configuration;; Need to unlock table of CDA's (|CDATabHndl) when exiting.  setuptab (called by; initstuff (below) locked the table.;	lda |CDATabHndl+2	pha	lda |CDATabHndl	pha	_HUnlock		plb	jml oendcall0	ENDP	EXPORT initstuffinitstuff	PROC	lda #LeftBorder80	;default init assumes 80 column screen	sta |leftborder	lda #LeftBorder80-3	;start position for border of menu	sta |hpos	lda #0	sta |vpos	jsr setuptab	;sets up table of CDA strings	sep #$20	longa off	sta >$00C00d	sta >$00C001		lda >$00C02d	and #$08	bne NotInternalSlot3	lda #0	sta >$0007FBNotInternalSlot3	rep #$20	longa on;; Set up screen holes to the values CDA expect;		rts	ENDPgotreturn	PROC EXPORT	longmx	lda |curcda	beq conpan	cmp #$FF	beq quitcode	jsr openda	jmp choosecdaWarmconpan	shortmx	lda #$00	; set b to bank zero	pha	plb	jsl toctrl_panel	longmx	jmp choosecdaWarmquitcode	jmp done	ENDPmonkeyin	PROC EXPORT	shortmx	lda $C000	;read keyboard	bpl monkeyin	;wait for keypress	sta $C010	;acknowledge keypress: clear keyboard	longmx	rts	ENDP	EXPORT evntkeyinevntkeyin	PROC	pushword #$00	; result***	pushword #$FFFF	;event mask -- keyboard only	pushword #$0428	;keydown and autokey only (12-Feb-91 DAL) + deskAcc (23-Feb-91)	pea evntrec>>16	pea evntrec**$FFFF	_GetNextEvent	pla	beq evntkeyin	; if 0 we don't handle	lda |evntrec	cmp #$03	beq  @1	; if keydown then exit	cmp #$05	bne evntkeyin	; if not autokey then skip@1	lda |message	and #$00FF	; make sure we only	have bottom byte	rts	ENDP	EXPORT pg2kludgepg2kludge	PROC	DC.L foofoo	DC.B $16	DC.B 'Alternate Display Mode'	DC.L open	DC.L AnRTLopen	shortmx	phb	lda #$00	pha	plb	jsl topg2kludge	plb	longmxAnRTL	rtl	ENDP************************************************************************ This routine displays the CDAs** The Pascal string list of CDA names is assumed to be setup already** The first DA shown is in |firstmenuitem (0 = first one = Control Panel)** |numdas contains the number of CDAs in the list** This routine is called at the beginning and everytime the display * scrolls.** Added by Konstantin Othmer Sept 21, 1988*****************************************************************	EXPORT UpdateCDAMenuUpdateCDAMenu	PROC* Set cursor to first location.	lda |leftborder	sta |hpos	lda #Top-1	;vertical text start position  	sta |vpos;; check if jumper is in; force it in for testing purposes;	jsr panelactive	bcc test2	;panel active => goto test2;;control panel not active - force firstmenuitem to 1 if it is 0 and same with curcda;	lda |curcda	bne test1	inc a	sta |curcda	sta |firstmenuitemtest1	lda |firstmenuitem	bne test2	inc a	sta |firstmenuitemtest2* If we are at item 0, print a blank line and 'control panel'	lda |firstmenuitem	bne Update0*We're @ top.  Blank uparrows if they are there by drawing blank line		lda #>blankline	sta temp2+1	lda #<blankline	sta temp2	jsr MyWriteCString	lda |leftborder	sta |hpos	inc |vpos		lda #>blankline	;blank control panel line to the end	sta temp2+1	lda #<blankline	sta temp2	jsr MyWriteCString	lda |leftborder	sta |hpos	lda #0	;normal text	ldy #0	;control panel	jsr writedaname	;print control panel: item 0	inc |vpos	ldy #1	;y-reg contains number of 1st item to do	bra Update1Update0;not at top.  print up arrows @ top-1;; If control panel enabled => goto test3;	jsr panelactive	bcc test3;; control panel not enabled: skip arrows when 1,1;	lda |firstmenuitem	cmp #1	bne test3;; Blank uparrows line;	lda #>blankline	sta temp2+1	lda #<blankline	sta temp2	jsr MyWriteCString	bra test4test3	lda #>uparrows	sta temp2+1	lda #<uparrows	sta temp2	jsr MyWriteCStringnttest4	lda |leftborder	sta |hpos	inc |vpos	ldy |firstmenuitemUpdate1	lda #0	pha	;set up flag for quit item	lda |numdas	;calculate number of items to print*number of items to print is numdas - firstmenuitem +1	sec	;x-reg will contain number of items to do	sbc |firstmenuitem	tax	lda |firstmenuitem	;Did we do control panel (above)?	bne Update2	;If we didn't, branch.*This section assumes control panel done.	cpx #NumLines-2	;Control panel and quit each take up one line	bcc Update4	;If 13 or less, there is quit item: branch	beq Update4	ldx #NumLines-1	;print maximum w/ control panel & no quit	lda #$ffff	;signal no quit item	sta 1,s	bra Update4Update2* No Control Panel	inx	cpx #NumLines	;Total length of display	bcc Update4	;branch on 14 or less	ldx #NumLines	;print maximum w/o control panel & no quit	lda #$ffff	;signal no quit item	sta 1,sUpdate4		jsr PrintDAList	;Print list of DAs* Handle Quit Item	lda |leftborder	sta |hpos	pla	;$ff signals no quit item, 0 signals quit	bne DoDownArrows	lda |bottomline	sta |vpos	lda |leftborder	sta |hpos	lda #>blankline	sta temp2+1	lda #<blankline	sta temp2	jsr MyWriteCString	lda |leftborder	sta |hpos	lda #0	; normal	ldy #$FF	;quit item identification	jsr writedaname* Here we erase bottom row.  It may contain down arrows which we don't want.	inc |vpos		lda #>blankline	sta temp2+1	lda #<blankline	sta temp2	jsr MyWriteCString		bra UpdateDoneDoDownArrows;; There is no quit item, so there must be more.  A "*** more ***" message shows this.;		lda #>blankline	sta temp2+1	lda #<blankline	sta temp2	jsr MyWriteCString	lda |leftborder	sta |hpos		lda #>downarrows	sta temp2+1	lda #<downarrows	sta temp2	jsr MyWriteCStringntUpdateDone		rts	ENDP	************************************************************************ PrintDAList**  Prints an excerpt from a list of C-strings** y-reg has # of 1st item to print (list starts at 1)* x-reg has # of items to print** Routine assumes initial print location is set up ** Everything printed in normal (not inverse) type** Added by Konstantin Othmer Sept 21, 1988***********************************************************************	EXPORT PrintDAListPrintDAList	PROC	inxPrintC1	dex	;Number items left zero?	beq PrintCDone		phx	phy	lda |leftborder	sta |hpos	ply	phy	lda #0	;normal	jsr writedaname	;does not change |hpos	clc	;a-reg contains length of da string	adc |hpos	sta |hposPrintLoop	lda |leftborder	clc	adc #36	;screen width	cmp |hpos	;have we filled to the right border yet?	beq LoopDone	lda #' '	jsr Mycout	;blank char	inc |hpos	bra PrintLoopLoopDone	inc |vpos	;advance vertical position	ply	plx	iny	bra PrintC1PrintCDone	rts	ENDP************************************************************************ PanelActive**  Checks whether or not to display the control panel.  This is set* via a jumper on the board.  The jumper controls bit 7 of $00C046.  If* bit 7 of $00C046 = 0 then we show the control panel and return with the * carry clear.  Otherwise the carry is set.* *PanelActive	PROC EXPORT	pha	phx	phy*** added 7-Jul-92 DAL -- For ROM 1, there is no Control Panel Disable jumper	pha	pha	pha	pha	;space for results	pha	pha	pha	;A, X, Y (who cares)	pea $FE1F	_FWEntry	ply	;Y value	plx	;X value	pla	;A value	pla	;P value	cpy #3	;Is this ROM 3?	bne PanelShow*** end 7-Jul-92	pushlong #IsPanelActive	pushlong #ReadLocation	pea $0009	;read location and store result at IsPanelActive	_ReadKeyMicroMemory		lda >IsPanelActive	and #$0040	;save bit 6	beq PanelShow	sec	;don't show control panel	bra PanelDone	PanelShow	clc	;show control panelPanelDone	ply	plx	pla	rts	ReadLocation	dc.l $00E8	;key micro $E8 bit 6 has control panel jumper	ENDP************************************************************************ SetPanelActive**  Checks whether or not to display the control panel.  This is set* via a jumper on the board.  The jumper controls bit 7 of $00C046.  If* bit 7 of $00C046 = 0 then we show the control panel and return with the * carry clear.  Otherwise the carry is set.*****************************************************************SetPanelActive	PROC EXPORT;	pha;	sep #$20	;8 bit m;	longa off;	lda >$00C060;	rep #$20;	longa on;	and #$0080;	eor #$0080	;change sense of bit;	sta >IsPanelActive;	pla	rts	ENDP	************************************************************************ Sends character in a to $FDED*****************************************************************	EXPORT coutcout	PROC;	pea 00	; space for result;	pea 00	; space for result;	pea 00	; space for result;	pea 00	; space for result	pha	; space for result (DAL)	pha	; space for result (DAL)	pha	; space for result (DAL)	pha	; space for result (DAL)	pha	; acc at entry;	pea 00	; xreg at entry;	pea 00	; yreg at entry	pha	; xreg at entry (DAL)	pha	; yreg at entry (DAL)	pea $FDED	_FWEntry	pla	pla	pla	pla	rts	ENDP************************************************************************ Screen driver:  A-reg contains character to print***********************************************************************	EXPORT MyCoutMyCout	PROC	and #$00FF	pha	;save character to print	jsr SetScreenLoc	ldx |CurScreenLoc	cpx #$400	bcs DoBank1	lda >$400,x	;screen	and #$FF00	ora 1,s	sta >$400,x	bra Bank0DoneDoBank1	txa	and #$03FF	tax	lda >$010400,x	;screen	and #$FF00	ora 1,s	sta >$010400,xBank0Done	pla		rts		ENDP	************************************************************************ Sets SetScreenLoc to position specified in Hpos and Vpos.  Uses MyCout.*****************************************************************	EXPORT SetScreenLocSetScreenLoc	PROC;;Calculate starting position.  Lookup ypos start and then add xpos;	lda |Vpos	asl a	tax	lda >ScreenTab,x	;get starting screen location	sta |CurScreenLoc	lda |Leftborder	cmp #4	;if less than 4, then 40 column mode	bcc FortyColumn;; Do 80 column stuff.;	lda |Hpos	pha	lsr a	clc	adc |CurScreenLoc	sta |CurScreenLoc	pla	lsr a	;odd or even position?	bcs OnBank0	lda |CurScreenLoc	ora #$400	sta |CurScreenLocOnBank0		bra AllDone	FortyColumn	lda |Hpos	clc	adc |CurScreenLoc	sta |CurScreenLocAllDone	rtsScreenTab	dc.w $000,$080,$100,$180,$200,$280,$300,$380	dc.w $028,$0A8,$128,$1A8,$228,$2A8,$328,$3A8	dc.w $050,$0D0,$150,$1D0,$250,$2D0,$350,$3D0		ENDP************************************************************************ Faster writeline routine.  Uses MyCout.**  Assumes pointer to p-string is in temp2***********************************************************************	EXPORT MyWriteLineMyWriteLine	PROC	lda [temp2]	and #$3f	;get string length	inc a	;offset because compare is done before print	pha	ldy #1PrintLoop	lda [temp2],y*** added 30-Sep-91 DAL -- support Ctrl-N for normal video	and #$007f	cmp #$000E	bne @notCtrlN	sep #$20	longa off	lda #$FF	sta >$32	rep #$20	longa on	bra Did1Character@notCtrlN*** end 30-Sep-91 DAL	bit $000031	;bit 7 of inverse flag	bmi NormalVideo		and #$7F	pha;;check for upper case inverse text;	and #$20	bne ItsLowerCase	pla	and #$BF	;reset bit 6	pha	ItsLowerCase	pla	bra DoVideoNormalVideo	ora #$80DoVideo	phy	jsr Mycout		inc |hpos	plyDid1Character	iny	tya	cmp 1,s		bne PrintLoop	pla	;clear stack	rts	ENDP************************************************************************ Faster writeCString routine.  Uses MyCout.**  Assumes pointer to p-string is in temp2*****************************************************************	EXPORT MyWriteCStringMyWriteCString	PROC	ldx |hpos	phx	Translate	ldy #0PrintLoop	lda [temp2],y	and #$FF	beq Done	bit $000031	;bit 7 of inverse flag	bmi NormalVideo		and #$7F	pha;;check for upper case inverse text;	and #$20	bne ItsLowerCase	pla	and #$BF	;reset bit 6	pha	ItsLowerCase	pla	bra DoVideoNormalVideo	ora #$80DoVideo	phy	jsr Mycout		inc |hpos	ply	iny	bra PrintLoop	Done	plx	stx |hpos	rts;; don't translate characters;	EXPORT MyWriteCStringntMyWriteCStringnt		ldx |hpos	phx	ldy #0NoTLoop	lda [temp2],y	and #$FF	beq Done	phy	jsr Mycout		inc |hpos	ply	iny	bra NoTLoop	ENDP;-----------------------------------------------------------; Write the name of the da corresponding to the number in the y; register at the current cursor position. If the accumulator is zero; then the item is drawn in 'normal' mode. If non-zero, the	name is; displayed in inverse mode. Note that the routine assumes that; cdatabptr is valid and cdatab is locked.	EXPORT writedanamewritedaname	PROC	cmp #$00	bne inverse	shortmx	lda #$FF;;;	sta $000032	; clear the inverse	flag;;;	longmx	bra continverse	shortmx	lda #$7Fcont	sta $000032	; set the inverse flag	longmx;;;cont	cpy #$00	bne cont1	ldy #$06	; offset to control	panel string;;;	jsr drbltin	; write the string;;;	rts	bra drbltincont1	cpy #$FF	bne cont2	ldy #$0A	; offset to quit string;;;	jsr drbltin;;;	rts	bra drbltincont2	jsr DerefCDAy	;made subroutine 12-Feb-91 DAL	lda |hpos	pha	jsr MyWriteline		pla	sta |hpos	lda [temp2]	;length of string	and #$3f	;only byte long	rtsdrbltin	phy	lda |dastrptr	; high part	sta temp1	lda |dastrptr+2	; lo part	sta temp1+2	ply	lda [temp1],y	sta temp2+2	dey	dey	lda [temp1],y	sta temp2	jsr MyWriteCString	rts	ENDP************************************************************************ SearchCDALetter -- move to the next CDA starting with the*                    specified character (in A)** (The current selection has already been unhilited, and the* caller will hilite the new one when we get back.  We need* to return a valid curcda and firstmenuitem, and if we scroll* we need to call UpdateCDAMenu in here.)***********************************************************************SearchCDALetter	proc export	jsr upcase	pha	;keep target value at 1,s	ldx |numdas	inx	inx		ldy |curCDA@find	jsr NextCDAy	jsr GetCDALetterY	cmp 1,s	beq @gotIt	dex	bne @find	pea $8008	;bad keypress, default to silence	_SysBeep2@exit	pla	;remove target value from stack	rts@gotIt	sty |curcda	jsr GetCDANum	;Quit=NumDAs+1*** If current item is less than first menu item, it's invalid.	cmp |FirstMenuItem	bcc @RecalcFirst*** If current item is greater than or equal to first item + NumLines,*** it's invalid.  In other words, if current item minus NumLines is*** greater than or equal to first item, current item is invalid (signed*** comparison).	sec	sbc #NumLines	cmp |FirstMenuItem	bmi @exit	;no problem** RecalcFirst--current item is out of range, so we need to figure out* a good place to scroll to.*@RecalcFirst	stz |FirstMenuItem	;anticipate scrolling to the top	jsr GetCDANum	;Quit=NumDAs+1	sbc #NumLines-3	;why 3?  It works.	bcc @scrollTheThing	;scroll to the top	beq @scrollTheThing	sta |FirstMenuItem	lda |curcda	cmp #$ff	;Quit?  Force to bottom.	bne @scrollTheThing	dec |FirstMenuItem	dec |FirstMenuItem@scrollTheThing	jsr UpdateCDAMenu	bra @exit** GetCDANum--return curcda, with $FF (Quit) translated into NumDAs+1*	export GetCDANumGetCDANum	lda |curcda	cmp #$00ff	;translate $FF (Quit) into NumDAs+1	bne @1	lda |numdas	inc a@1	rts** GetCDALetterY** Input:  CDA number in Y ($FF=Quit, 0=Control Panel, 1..NumDAs=other)* Output: A (uppercase)*GetCDALetterY	tya	bne @NotLetterCP	lda #$43	;C for Control Panel	rts@NotLetterCP	cmp #$00ff	bne @NotLetterQuit	lda #$51	;Q for Quit	rts@NotLetterQuit	phy	jsr DerefCDAy	ldy #1	lda [temp2],y	;CDA names sometimes have bit 7 on!	plyupcase	and #$007f	cmp #$61	;'a', high bit off	bcc @1	cmp #$7a+1	;'z'+1, high bit off	bcs @1	and #$5f@1	rts** NextCDAy -- advance Y to the next CDA** (If Y = NumDAs, advance to $FF; else advance by 1, and keep* bottom 8 bits.  Advances from Quit($FF) to Control Panel(0),* from Control Panel(0) to 1.)*NextCDAy	cpy |NumDAs	bne @1	ldy #$fe@1	iny	tya	and #$00ff	tay	rts	EndP************************************************************************ DerefCDAy -- split into a subroutine 12-Feb-91 DAL** Input: Y = 1..NumDAs* Output: temp2 = pointer to CDA header (pString, entry, shutdown)***********************************************************************DerefCDAy	proc export	lda |cdatabptr	; copy the table pointer into	sta temp2	; the direct page	lda |cdatabptr+2	sta temp2+2	tya	dec a	asl a	; adjust y	asl a	tay	lda [temp2],y	; get a handle to the da	sta temp1	iny	iny	lda [temp2],y	sta temp1+2	jsr deref	; deref the handle	rts	EndP; set up cdatabptr and lock the table	EXPORT setuptabsetuptab	PROC	lda |CDATabHndl+2	pha	sta temp1+2	lda |CDATabHndl	pha	sta temp1	_HLock	jsr deref	lda temp2	sta |cdatabptr	lda temp2+2	sta |cdatabptr+2	rts	ENDP**********************************************************************	EXPORT opendaopenda	PROC	sei	tay	shortmx	lda #$FF	sta $000032	; clear the inverse	flag	longmx	lda |cdatabptr	; copy the table pointer into	sta temp2	; the direct page	lda |cdatabptr+2	sta temp2+2	tya	dec a	asl a	; adjust y	asl a	tay	lda [temp2],y	; get a handle to the da	sta temp1	iny	iny	lda [temp2],y	sta temp1+2	jsr deref	; deref the handle	lda [temp2]	; get the length	and #$00FF	tay	iny	phk	; set up return address	per ret-1	lda [temp2],y	; get low part of open addr	tax	; save	iny	iny	lda [temp2],y	; get high part	sep #$20	; 8-bit m	pha	; push bank info	rep #$30	dex	phx	; push open address	cli	; enable interrupts	for the da	rtl	; call the routineret	rts	; all done	ENDP	EXPORT derefderef	PROC	ldy #$02	lda [temp1]	sta temp2	lda [temp1],y	sta temp2+2	rts	ENDP	END